ALTER TABLE orders ADD COLUMN payment_method VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'cod', ADD COLUMN payment_reference VARCHAR(40) CHARACTER SET ascii COLLATE ascii_bin NULL, ADD COLUMN payment JSON NULL, ADD COLUMN payment_due_at DATETIME(6) NULL, ADD COLUMN paid_at DATETIME(6) NULL, ADD CONSTRAINT orders_payment_status_ck CHECK (payment_status IN ('pending','paid','expired')), ADD CONSTRAINT orders_payment_method_ck CHECK (payment_method IN ('cod','online')), ADD UNIQUE KEY orders_payment_reference (user_id,payment_reference), ADD KEY orders_payment_due (payment_status,payment_due_at)
